       r.file_size, r.file_type, r.cover_image, r.view_count, r.download_count, r.collect_count,
       r.uploader_id, r.uploader_name, r.status, r.create_time, r.update_time,
       c.category_name
FROM resource_info r
LEFT JOIN resource_category c ON r.category_id = c.category_id


