SELECT r.resource_id, r.title, r.description, r.category_id, r.file_name, r.file_path, r.file_size, r.file_type, r.cover_image, r.view_count, r.download_count, r.collect_count, r.uploader_id, r.uploader_name, r.status, r.create_time, r.update_time, c.category_name FROM resource_info r LEFT JOIN resource_category c ON r.category_id = c.category_id
AND (r.title LIKE CONCAT('%', #{params.keyword}, '%') OR r.description LIKE CONCAT('%', #{params.keyword}, '%'))
AND r.category_id = #{params.categoryId}
AND r.file_type = #{params.fileType}
AND r.status = #{params.status}
